comments:
/* ===== 小狗日记小票 · 评述模块（票据连打，分割线分隔） ===== */
.be-comments {
  background: #ffffff;
  border-top: 1px dashed #d8cfb8;
  font-family: "Nightgazer 16", "Fixedsys", "Courier New", Consolas, monospace;
}
.be-comment {
  display: flex;
  gap: 8px;
  padding: 8px 14px;
  border-bottom: 1px dashed #eee7d4;
}
.be-comment:last-child { border-bottom: none; }
.be-comment-avatar {
  width: 24px;
  height: 24px;
  border-radius: 4px;
  background-size: cover;
  background-position: center;
  background-color: #f0ead9;
  flex-shrink: 0;
}
.be-comment-main { flex: 1; min-width: 0; }
.be-comment-meta { display: flex; align-items: baseline; flex-wrap: wrap; gap: 3px 6px; }
.be-comment-name { font-size: 11.5px; color: #000; font-weight: 700; }
.be-comment-id { font-size: 10.5px; color: #555; }
.be-comment-time { font-size: 10.5px; color: #888; }
.be-comment-text { font-size: 12px; color: #000; line-height: 1.55; margin-top: 2px; white-space: pre-wrap; overflow-wrap: break-word; }
.be-comment[data-kind="user"] .be-comment-name { color: #000; }
